"use client"

import { useEffect, useState } from "react"
import { BookingForm } from "@/components/booking-form"
import { Sparkles } from "lucide-react"
import { publicProfissionalService, type ServicoPublico } from "@/lib/services/public-profissional-service"

interface DesignerInfo {
  name: string
  description?: string
  services: Array<{
    id: string
    name: string
    duration: number
  }>
}

export default function AgendarPage({ params }: { params: { designerId: string } }) {
  const [designerInfo, setDesignerInfo] = useState<DesignerInfo | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const carregarDados = async () => {
      setIsLoading(true)
      setError(null)
      
      try {
        console.log('🔍 Carregando dados da profissional:', params.designerId)
        
        // Busca dados da profissional e serviços em paralelo
        const [dadosProfissional, servicos] = await Promise.all([
          publicProfissionalService.obterDadosPublicos(params.designerId),
          publicProfissionalService.listarServicos(params.designerId),
        ])

        console.log('✅ Dados carregados:', { dadosProfissional, servicos })

        setDesignerInfo({
          name: dadosProfissional.nomeFantasia,
          description: dadosProfissional.descricao,
          services: servicos.map((s: ServicoPublico) => ({
            id: s.id,
            name: s.nome,
            duration: s.duracaoMin,
          })),
        })
      } catch (err: any) {
        console.error('❌ Erro ao carregar dados:', err)
        setError('Não foi possível carregar as informações. Tente novamente mais tarde.')
      } finally {
        setIsLoading(false)
      }
    }

    carregarDados()
  }, [params.designerId])

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-primary/5 via-background to-accent/5">
        <div className="container mx-auto px-4 py-12 max-w-2xl">
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 mb-4">
              <Sparkles className="w-8 h-8 text-primary animate-pulse" />
            </div>
            <p className="text-muted-foreground">Carregando...</p>
          </div>
        </div>
      </div>
    )
  }

  if (error || !designerInfo) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-primary/5 via-background to-accent/5">
        <div className="container mx-auto px-4 py-12 max-w-2xl">
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-destructive/10 mb-4">
              <Sparkles className="w-8 h-8 text-destructive" />
            </div>
            <h1 className="text-2xl font-bold mb-2">Ops!</h1>
            <p className="text-muted-foreground">{error || 'Profissional não encontrada.'}</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary/5 via-background to-accent/5">
      <div className="container mx-auto px-4 py-12 max-w-2xl">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 mb-4">
            <Sparkles className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-4xl font-bold text-balance mb-2">{designerInfo.name}</h1>
          {designerInfo.description && (
            <p className="text-muted-foreground mb-2">{designerInfo.description}</p>
          )}
          <p className="text-muted-foreground">Agende seu horário de forma rápida e fácil</p>
        </div>

        <BookingForm designerInfo={designerInfo} designerId={params.designerId} />
      </div>
    </div>
  )
}
